     7	}
     8	
     9	const PROCESSING_FEE = 5;
    10	const FIRST_INSURANCE_SURCHARGE = 0.1;
    11	
    12	// Components (e.g. runes, moonstones) share one price-list tariff.
    13	const COMPONENT_BASE_PREMIUM = 25;
    14	
    15	const BASE_PREMIUMS: Record<string, number> = {
    16	  sword: 100,
    17	  amulet: 60,
    18	  staff: 80,
    19	  potion: 40,
    20	  rune: COMPONENT_BASE_PREMIUM,
    21	  moonstone: COMPONENT_BASE_PREMIUM,
    22	};
    23	
    24	const PREMIUM_PRECISION = 1e-9;
    25	
    26	function roundUpInMHPCOFavor(amount: number): number {
    27	  return Math.ceil(amount - PREMIUM_PRECISION);
    28	}
    29	
    30	const BLOCK_SIZE = 3;
    31	const BLOCK_BASE_PREMIUM = 60;
    32	
    33	function countByType(items: Item[]): Map<string, number> {
    34	  const counts = new Map<string, number>();
    35	  for (const item of items) {
    36	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
    37	  }
    38	  return counts;
    39	}
    40	
    41	// A building block is offered for exactly 3 alike components.
    42	function blockOfferApplies(type: string, count: number): boolean {
    43	  return type === "rune" && count === BLOCK_SIZE;
    44	}
    45	
    46	function typeBasePremium(type: string, count: number): number {
    47	  if (blockOfferApplies(type, count)) {
    48	    return BLOCK_BASE_PREMIUM;
    49	  }
    50	  return count * BASE_PREMIUMS[type];
    51	}
    52	
    53	function policyBasePremium(items: Item[]): number {
    54	  let total = 0;
    55	  for (const [type, count] of countByType(items)) {
    56	    total += typeBasePremium(type, count);
    57	  }
    58	  return total;
    59	}
    60	
    61	export function quote(customer: Customer, items: Item[], previousContracts: number): number {
    62	  const basePremium = policyBasePremium(items);
    63	  const modifiedPremium = basePremium + basePremium * FIRST_INSURANCE_SURCHARGE;
    64	  return roundUpInMHPCOFavor(modifiedPremium + PROCESSING_FEE);
    65	}
